const std = @import("std");
const C = @import("canvas.zig");
fn code(point: C.Point, clip: C.Rect) u4 { var result: u4 = 0; if (point.x < clip.x0) result |= 1; if (point.x > clip.x1) result |= 2; if (point.y < clip.y0) result |= 4; if (point.y > clip.y1) result |= 8; return result; }
pub fn segment(input: C.Segment, clip: C.Rect) ?C.Segment { var result = input; while (true) { const first_code = code(result.first, clip); const last_code = code(result.last, clip); if (first_code == 0 and last_code == 0) return result; if (first_code & last_code != 0) return null; const outside_code = if (first_code != 0) first_code else last_code; const a = if (first_code != 0) result.first else result.last; const b = if (first_code != 0) result.last else result.first; var point: C.Point = undefined;
        if (outside_code & 4 != 0) point = .{ .x = a.x + C.roundRatio((b.x - a.x) * (clip.y0 - a.y), b.y - a.y), .y = clip.y0 } else if (outside_code & 8 != 0) point = .{ .x = a.x + C.roundRatio((b.x - a.x) * (clip.y1 - a.y), b.y - a.y), .y = clip.y1 } else if (outside_code & 2 != 0) point = .{ .x = clip.x1, .y = a.y + C.roundRatio((b.y - a.y) * (clip.x1 - a.x), b.x - a.x) } else point = .{ .x = clip.x0, .y = a.y + C.roundRatio((b.y - a.y) * (clip.x0 - a.x), b.x - a.x) };
        if (first_code != 0) result.first = point else result.last = point;
    } }
fn inside(point: C.Point, axis: usize, limit: i64, minimum: bool) bool { const value = if (axis == 0) point.x else point.y; return if (minimum) value >= limit else value <= limit; }
fn intersection(a: C.Point, b: C.Point, axis: usize, limit: i64) C.Point { return if (axis == 0) .{ .x = limit, .y = a.y + C.roundRatio((limit - a.x) * (b.y - a.y), b.x - a.x) } else .{ .x = a.x + C.roundRatio((limit - a.y) * (b.x - a.x), b.y - a.y), .y = limit }; }
pub fn polygon(input: []const C.Point, clip: C.Rect) []const C.Point { const Boundary = struct { axis: usize, limit: i64, minimum: bool }; const boundaries = [_]Boundary{ .{ .axis = 0, .limit = clip.x0, .minimum = true }, .{ .axis = 0, .limit = clip.x1 + 1, .minimum = false }, .{ .axis = 1, .limit = clip.y0, .minimum = true }, .{ .axis = 1, .limit = clip.y1 + 1, .minimum = false } }; var vertices = input;
    for (boundaries) |boundary| { var output: std.ArrayList(C.Point) = .empty; for (vertices, 0..) |last, i| { const first = vertices[if (i == 0) vertices.len - 1 else i - 1]; const last_inside = inside(last, boundary.axis, boundary.limit, boundary.minimum); const first_inside = inside(first, boundary.axis, boundary.limit, boundary.minimum); if (last_inside) { if (!first_inside) C.push(C.Point, &output, intersection(first, last, boundary.axis, boundary.limit)); C.push(C.Point, &output, last); } else if (first_inside) C.push(C.Point, &output, intersection(first, last, boundary.axis, boundary.limit)); } vertices = output.items; } return vertices;
}
